prime = [1] * 10003
primes = []

def seive():
	for i in range(2, 10003):
		if prime[i]:
			for j in range(i * i, 10003, i):
				prime[j] = False
			primes.append(i)
t = int(input())
seive()
for testcase in range(t):
	n = int(input())
	v = list(map(int, input().split()))
	count = 0
	for i in range(1, n):
		if v[i] < v[i - 1]:
			count += v[i - 1] - v[i]
			v[i] = v[i - 1]
	ans = 10 ** 9
	for i in primes:
		if i > v[-1]:
			break
		required = 0
		tempans = count
		for j in v:
			if required < j:
				required = (j + i - 1) // i * i
			tempans += required - j
			if tempans > ans:
				break
		if ans > tempans:
			ans = tempans
	print(n) if v[-1] < 2 else print(ans)
